## 条件评估引擎

```go
// backend/internal/service/achievement_evaluator.go

type GameResult struct {
    GameID     string
    Mode       string
    Difficulty string
    Result     string  // "win" | "lose" | "draw" | "complete"
    Duration   int     // 秒
    Score      int
    Extra      map[string]interface{}  // 游戏特有数据
}

func EvaluateCondition(cond map[string]interface{}, result GameResult, history UserHistory) bool {
    switch cond["type"] {
    case "game_id":
        return result.GameID == cond["value"]
    case "difficulty":
        return result.Difficulty == cond["value"]
    case "result":
        return result.Result == cond["value"]
    case "time_lt":
        secs := int(cond["value"].(float64))
        return result.Duration < secs
    case "time_gt":
        secs := int(cond["value"].(float64))
        return result.Duration > secs
    case "score_gte":
        return result.Score >= int(cond["value"].(float64))
    case "win_streak":
        n := int(cond["value"].(float64))
        return history.WinStreak(result.GameID) >= n
    case "total_games":
        n := int(cond["value"].(float64))
        return history.TotalGames(result.GameID) >= n
    case "and":
        subConds := cond["conditions"].([]interface{})
        for _, sub := range subConds {
            if !EvaluateCondition(sub.(map[string]interface{}), result, history) {
                return false
            }
        }
        return true
    case "or":
        subConds := cond["conditions"].([]interface{})
        for _, sub := range subConds {
            if EvaluateCondition(sub.(map[string]interface{}), result, history) {
                return true
            }
        }
        return false
    }
    return false
}
```

支持 `and`/`or` 嵌套，可以表达任意复杂的解锁条件。

